#include <iostream>
#include <queue>
using namespace std;
char gridA[20][20], gridB[20][20];
queue<pair<int,int>> q;
int dist[20][20], dist3[11][11][11][11];
int dx[4]={-1,1,0,0}, dy[4]={0,0,-1,1};
struct edge {
    int u,v,flow,capacity,link;
} edges[200005];
int edgeCount, head[505], parent[505], visited[505], source=501, sink=502, totalFlow, rows, cols, level[505];

inline void addEdge(int u, int v, int w) {
    edges[++edgeCount]={u,v,0,w,head[u]};
    head[u]=edgeCount;
    edges[++edgeCount]={v,u,0,0,head[v]};
    head[v]=edgeCount;
}

inline bool bfs() {
    queue<int> q2;
    for(int i=0;i<=sink;i++) visited[i]=level[i]=0;
    q2.push(source);
    visited[source]=1;
    level[source]=1;
    while(!q2.empty()) {
        int x=q2.front(); q2.pop();
        for(int i=head[x];i;i=edges[i].link) {
            if(!visited[edges[i].v] && edges[i].flow<edges[i].capacity) {
                parent[edges[i].v]=i;
                q2.push(edges[i].v);
                visited[edges[i].v]=1;
                level[edges[i].v]=level[x]+1;
                if(edges[i].v==sink) return true;
            }
        }
    }
    return false;
}

inline int dfs(int x, int flow) {
    if(x==sink || flow==0) return flow;
    int remaining=flow;
    for(int i=head[x];i;i=edges[i].link) {
        if(edges[i].capacity>edges[i].flow && level[edges[i].v]==level[x]+1) {
            int delta=dfs(edges[i].v, min(remaining, edges[i].capacity - edges[i].flow));
            if(delta==0) level[edges[i].v]=0;
            edges[i].flow+=delta;
            edges[((i-1)^1)+1].flow-=delta;
            remaining-=delta;
            if(remaining==0) break;
        }
    }
    return flow - remaining;
}

inline void maxFlow() {
    while(bfs()) totalFlow+=dfs(source, 1000000007);
}

int main() {
    int n, t;
    cin >> n >> t;
    for(int i=1;i<=n;i++) {
        for(int j=1;j<=n;j++) {
            dist[i][j]=10000;
            cin >> gridA[i][j];
            if(gridA[i][j]=='Z') {
                q.push({i,j});
                dist[i][j]=0;
            }
            if(gridA[i][j]<='9') addEdge(source, (i-1)*n+j, gridA[i][j]-'0');
        }
    }
    while(!q.empty()) {
        int x=q.front().first, y=q.front().second; q.pop();
        for(int i=0;i<4;i++) {
            int nx=x+dx[i], ny=y+dy[i];
            if(nx>0 && ny>0 && nx<=n && ny<=n && gridA[nx][ny]<='9' && dist[nx][ny]>dist[x][y]+1) {
                dist[nx][ny]=dist[x][y]+1;
                q.push({nx,ny});
            }
        }
    }
    for(int i=1;i<=n;i++) {
        for(int j=1;j<=n;j++) {
            if(gridA[i][j]>'9') continue;
            for(int k=1;k<=n;k++)
                for(int l=1;l<=n;l++)
                    dist3[i][j][k][l]=10000;
            q.push({i,j});
            dist3[i][j][i][j]=0;
            while(!q.empty()) {
                int x=q.front().first, y=q.front().second; q.pop();
                for(int f=0;f<4;f++) {
                    int nx=x+dx[f], ny=y+dy[f];
                    if(nx>0 && ny>0 && nx<=n && ny<=n && gridA[nx][ny]<='9' && dist3[i][j][nx][ny]>dist3[i][j][x][y]+1 && dist[x][y]<dist[nx][ny]) {
                        dist3[i][j][nx][ny]=dist3[i][j][x][y]+1;
                        q.push({nx,ny});
                    }
                }
            }
            for(int k=1;k<=n;k++) {
                for(int l=1;l<=n;l++) {
                    if(dist3[i][j][k][l]<=min(dist[k][l], t))
                        addEdge((i-1)*n+j, (k-1)*n+l+100, 10000);
                }
            }
        }
    }
    for(int i=1;i<=n;i++) {
        for(int j=1;j<=n;j++) {
            cin >> gridB[i][j];
            if(gridB[i][j]<='9') addEdge((i-1)*n+j+100, sink, gridB[i][j]-'0');
        }
    }
    maxFlow();
    cout << totalFlow;
    return 0;
}
